/** The steps of a time list (D105 (14)): from [from] to [to] in [stepMinutes]; default half hours 05:00–23:30. */
fun sbTimeSteps(from: LocalTime = LocalTime.of(5, 0), to: LocalTime = LocalTime.of(23, 30), stepMinutes: Long = 30L): List<LocalTime> {
    require(stepMinutes > 0L) { "sbTimeSteps: stepMinutes > 0" }
    val out = mutableListOf<LocalTime>()
    var at = from
    while (!at.isAfter(to)) {
        out += at
        val next = at.plusMinutes(stepMinutes)
        if (next.isBefore(at)) break   // past midnight
        at = next
    }
    return out
}

/**
 * A time row (D105 (13)): [label] in body, [text] in caption textMuted under it, the [time] in bodyStrong tabular and
 * the clock icon at the end; ≥ 56 dp, the whole row opens SbTimeSheet with [times], a press there calls [onChange].
 * [open] and [onOpenChange] let the app open and close the sheet (hoisted state); without [open] the row keeps it.
 */
@Composable
fun SbTimeRow(
    label: String,
    time: LocalTime,
    onChange: (LocalTime) -> Unit,
    modifier: Modifier = Modifier,
    text: String? = null,
    times: List<LocalTime> = sbTimeSteps(),
    hairline: Boolean = true,
    open: Boolean? = null,
    onOpenChange: (Boolean) -> Unit = {},
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val m = sbMessages()
    // the open state is the row's own unless the app passes [open]; the own one is not saved, so a rotation closes the
    // sheet, as before
    var ownOpen by remember { mutableStateOf(false) }
    val isOpen = open ?: ownOpen
    val setOpen: (Boolean) -> Unit = { if (open == null) ownOpen = it; onOpenChange(it) }
    // §14.34: each open is a new session of the sheet, keyed below, so a list place saved by an earlier session (the
    // sheet was open and scrolled at a rotation that closed it) is never restored into a later open; a sheet that
    // stays open through the change (an [open] the app saves) stays in its session and keeps its place
    val session = rememberSaveable(saver = SbTimeSession.Saver) { SbTimeSession() }
    if (isOpen != session.open) {
        if (isOpen) session.id++
        session.open = isOpen
    }
    val interaction = remember { MutableInteractionSource() }
    val pressed by interaction.collectIsPressedAsState()
    Row(
        modifier
            .fillMaxWidth()
            .heightIn(min = t.size.controlLg)
            .background(if (pressed) c.pressedFill else Color.Transparent)
            .drawBehind {
                if (hairline && !pressed) drawRect(c.border, Offset.Zero, Size(size.width, t.borderWidth.hairline.toPx()))
            }
            .sbFocusRingInset(interaction)
            .clickable(interactionSource = interaction, indication = null, role = Role.Button, onClick = { setOpen(true) })
            .semantics(mergeDescendants = true) { }
            .padding(horizontal = t.spacing.gutter, vertical = t.space.s2),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(t.space.s3),
    ) {
        Column(Modifier.weight(1f)) {
            SbWrapText(label, ty.body, c.text)
            if (text != null) SbWrapText(text, ty.caption, c.textMuted)
        }
        Text(
            m.timeOfDay(time),
            style = ty.bodyStrong.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings),
            color = c.text,
            softWrap = false,
        )
        Icon(SebaroIcons.Outline.Clock, contentDescription = null, tint = c.textMuted, modifier = Modifier.size(t.size.iconLg))
    }
    if (isOpen) {
        // the runtime's key() as sbKey: a call of `key` would hide the key event's `key` property from the import pool (§1)
        sbKey(session.id) {
            SbTimeSheet(
                times = times,
                selected = time,
                onPick = {
                    setOpen(false)
                    onChange(it)
                },
                onDismiss = { setOpen(false) },
                keepPlace = open != null,
            )
        }
    }
}

/** Which open of SbTimeRow's sheet this is and whether it is open (§14.34); saved, not a snapshot state. */
private class SbTimeSession(var id: Int = 0, var open: Boolean = false) {
    companion object {
        val Saver = listSaver<SbTimeSession, Int>(
            save = { listOf(it.id, if (it.open) 1 else 0) },
            restore = { SbTimeSession(it[0], it[1] == 1) },
        )
    }
}

/**
 * The time sheet (D105 (13)): SbBottomSheet with the head [title] („Uhrzeit wählen“) and one radio row per entry of
 * [times]; it opens fully, its list at most half the window high, with [selected] in view and two rows before it (more
 * only where the list ends); a press calls [onPick] (the caller closes it). A [selected] that is not in [times] is
 * inserted in order and chosen, and the list opens at it. Every open starts at [selected]: the list's place is not
 * saved, unless [keepPlace], where it lives through a configuration change while the sheet stays open; only for a
 * sheet the caller keeps open through it, and in a key() per open as SbTimeRow does, or a later open would start at
 * the old place (§14.34).
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SbTimeSheet(
    times: List<LocalTime>,
    selected: LocalTime,
    onPick: (LocalTime) -> Unit,
    onDismiss: () -> Unit,
    title: String = sbMessages().timeChoose,
    keepPlace: Boolean = false,
) {
    val m = sbMessages()
    // a saved time between the steps stands in its place in the list and is chosen, until a step is picked
    val shown = if (selected in times) times else (times + selected).sorted()
    val at = shown.indexOf(selected).coerceAtLeast(0)
    // not rememberLazyListState: that one is saved, and its place came back into the next open after a rotation had
    // closed the sheet (§14.34)
    val first = (at - 2).coerceAtLeast(0)
    val list = if (keepPlace) rememberSaveable(saver = LazyListState.Saver) { LazyListState(first) }
    else remember { LazyListState(first) }
    // the list is what the sheet shows: a half-open sheet laid its list out at full height past the screen's edge, so
    // the list met its end early (the review of the lane, CHECKS §32.4)
    val high = LocalConfiguration.current.screenHeightDp.dp / 2
    SbBottomSheet(
        onDismissRequest = onDismiss,
        sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true),
        title = title,
    ) {
        LazyColumn(Modifier.fillMaxWidth().heightIn(max = high).selectableGroup(), state = list) {
            // the member items(count): the list extension's import would join the shared pool (§1)
            items(shown.size) { i ->
                val time = shown[i]
                SbRadioRow(m.timeOfDay(time), time == selected, onClick = { onPick(time) })
            }
        }
    }
}
